### Configuration Specifications

**Secrets Manager Secret Configuration:**

```hcl
# Terraform configuration for Kafka Connect database credential
resource "aws_secretsmanager_secret" "database_credentials" {
  name        = "/msk/${var.cluster_name}/kafka-connect/${var.connector_name}/database-credentials"
  description = "${var.connector_name} database credentials with automatic rotation"
  kms_key_id  = aws_kms_key.kafka_secrets.id

  rotation_rules {
    automatically_after_days = var.rotation_interval_days  # 30, 60, or 90 based on sensitivity
  }

  tags = {
    Cluster     = var.cluster_name
    Component   = "kafka-connect"
    Connector   = var.connector_name
    Environment = var.environment
    Sensitivity = var.data_sensitivity  # Critical, High, Standard
    Owner       = var.service_owner
  }
}

resource "aws_secretsmanager_secret_version" "database_credentials" {
  secret_id = aws_secretsmanager_secret.database_credentials.id
  secret_string = jsonencode({
    username                = "kafka_${var.component}_${var.service}_${var.environment}"
    password                = random_password.db_password.result
    host                    = var.database_host
    port                    = var.database_port
    database                = var.database_name
    ssl_mode                = "require"
    created_at              = timestamp()
    rotation_interval_days  = var.rotation_interval_days
    expiration_date         = timeadd(timestamp(), "${365 * 24}h")  # 1 year
    service_owner           = var.service_owner
    jira_ticket             = var.provisioning_ticket
  })
}
```

**KMS Key Configuration:**

```hcl
resource "aws_kms_key" "kafka_secrets" {
  description             = "KMS key for Kafka secrets encryption"
  enable_key_rotation     = true
  deletion_window_in_days = 30

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM Root Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow Secrets Manager to use the key"
        Effect = "Allow"
        Principal = {
          Service = "secretsmanager.amazonaws.com"
        }
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey",
          "kms:CreateGrant"
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            "kms:ViaService" = "secretsmanager.${var.region}.amazonaws.com"
          }
        }
      },
      {
        Sid    = "Allow Kafka Connect to decrypt secrets"
        Effect = "Allow"
        Principal = {
          AWS = aws_iam_role.kafka_connect.arn
        }
        Action = [
          "kms:Decrypt",
          "kms:DescribeKey"
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            "kms:ViaService" = "secretsmanager.${var.region}.amazonaws.com"
          }
        }
      }
    ]
  })
}
```

**IAM Policy for Secret Access:**

```json
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Effect": "Allow",
      "Action": [
        "secretsmanager:GetSecretValue",
        "secretsmanager:DescribeSecret"
      ],
      "Resource": [
        "arn:aws:secretsmanager:us-east-1:123456789012:secret:/msk/msk-prod-cluster/kafka-connect/*"
      ]
    },
    {
      "Effect": "Allow",
      "Action": [
        "kms:Decrypt",
        "kms:DescribeKey"
      ],
      "Resource": "arn:aws:kms:us-east-1:123456789012:key/12345678-1234-1234-1234-123456789012",
      "Condition": {
        "StringEquals": {
          "kms:ViaService": "secretsmanager.us-east-1.amazonaws.com"
        }
      }
    }
  ]
}
```

**Kafka Connect Connector Configuration:**

```json
{
  "name": "claims-postgres-source",
  "config": {
    "connector.class": "io.confluent.connect.jdbc.JdbcSourceConnector",
    "tasks.max": "4",
    "connection.url": "jdbc:postgresql://${secretsManager:/msk/msk-prod-cluster/kafka-connect/claims-postgres-source/database-credentials:host}:${secretsManager:/msk/msk-prod-cluster/kafka-connect/claims-postgres-source/database-credentials:port}/${secretsManager:/msk/msk-prod-cluster/kafka-connect/claims-postgres-source/database-credentials:database}?sslmode=require",
    "connection.user": "${secretsManager:/msk/msk-prod-cluster/kafka-connect/claims-postgres-source/database-credentials:username}",
    "connection.password": "${secretsManager:/msk/msk-prod-cluster/kafka-connect/claims-postgres-source/database-credentials:password}",
    "config.providers": "secretsManager",
    "config.providers.secretsManager.class": "com.github.jcustenborder.kafka.config.aws.SecretsManagerConfigProvider",
    "config.providers.secretsManager.param.aws.region": "us-east-1"
  }
}
```

